      "content": "// Licensed to the .NET Foundation under one or more agreements.\n// The .NET Foundation licenses this file to you under the MIT license.\n\nnamespace Microsoft.DotNet.Cli.Telemetry;\n\n/// <summary>\n/// Base class for environment detection rules that can be evaluated against environment variables.\n/// </summary>\ninternal abstract class EnvironmentDetectionRule\n{\n    /// <summary>\n    /// Evaluates the rule against the current environment.\n    /// </summary>\n    /// <returns>True if the rule matches the current environment; otherwise, false.</returns>\n    public abstract bool IsMatch();\n}\n\n/// <summary>\n/// Rule that matches when any of the specified environment variables is set to \"true\".\n/// </summary>\ninternal class BooleanEnvironmentRule : EnvironmentDetectionRule\n{\n    private readonly Func<string, string?> _getEnvironmentVariable;\n    private readonly string[] _variables;\n\n    public BooleanEnvironmentRule(params string[] variables) : this(Environment.GetEnvironmentVariable, variables)\n    {\n    }\n\n    public BooleanEnvironmentRule(Func<string, string?> getEnvironmentVariable, params string[] variables)\n    {\n        _getEnvironmentVariable = getEnvironmentVariable ?? throw new ArgumentNullException(nameof(getEnvironmentVariable));\n        _variables = variables ?? throw new ArgumentNullException(nameof(variables));\n    }\n\n    public override bool IsMatch()\n    {\n        return _variables.Any(variable => EnvironmentVariableParser.ParseBool(_getEnvironmentVariable(variable), defaultValue: false));\n    }\n}\n\n/// <summary>\n/// Rule that matches when all specified environment variables are present and not null/empty.\n/// </summary>\ninternal class AllPresentEnvironmentRule : EnvironmentDetectionRule\n{\n    private readonly Func<string, string?> _getEnvironmentVariable;\n    private readonly string[] _variables;\n\n    public AllPresentEnvironmentRule(params string[] variables) : this(Environment.GetEnvironmentVariable, variables)\n    {\n    }\n\n    public AllPresentEnvironmentRule(Func<string, string?> getEnvironmentVariable, params string[] variables)\n    {\n        _getEnvironmentVariable = getEnvironmentVariable ?? throw new ArgumentNullException(nameof(getEnvironmentVariable));\n        _variables = variables ?? throw new ArgumentNullException(nameof(variables));\n    }\n\n    public override bool IsMatch()\n    {\n        return _variables.All(variable => !string.IsNullOrEmpty(_getEnvironmentVariable(variable)));\n    }\n}\n\n/// <summary>\n/// Rule that matches when any of the specified environment variables is present and not null/empty.\n/// </summary>\ninternal class AnyPresentEnvironmentRule : EnvironmentDetectionRule\n{\n    private readonly Func<string, string?> _getEnvironmentVariable;\n    private readonly string[] _variables;\n\n    public AnyPresentEnvironmentRule(params string[] variables) : this(Environment.GetEnvironmentVariable, variables)\n    {\n    }\n\n    public AnyPresentEnvironmentRule(Func<string, string?> getEnvironmentVariable, params string[] variables)\n    {\n        _getEnvironmentVariable = getEnvironmentVariable ?? throw new ArgumentNullException(nameof(getEnvironmentVariable));\n        _variables = variables ?? throw new ArgumentNullException(nameof(variables));\n    }\n\n    public override bool IsMatch()\n    {\n        return _variables.Any(variable => !string.IsNullOrEmpty(_getEnvironmentVariable(variable)));\n    }\n}\n\n/// <summary>\n/// Rule that matches when any of the specified sub-rules match.\n/// </summary>\ninternal class AnyMatchEnvironmentRule : EnvironmentDetectionRule\n{\n    private readonly EnvironmentDetectionRule[] _rules;\n\n    public AnyMatchEnvironmentRule(params EnvironmentDetectionRule[] rules)\n    {\n        _rules = rules ?? throw new ArgumentNullException(nameof(rules));\n    }\n\n    public override bool IsMatch()\n    {\n        return _rules.Any(rule => rule.IsMatch());\n    }\n}\n\n/// <summary>\n/// Rule that matches when an environment variable contains a specific value (case-insensitive).\n/// </summary>\ninternal class EnvironmentVariableValueRule : EnvironmentDetectionRule\n{\n    private readonly Func<string, string?> _getEnvironmentVariable;\n    private readonly string _variable;\n    private readonly string _expectedValue;\n\n    public EnvironmentVariableValueRule(string variable, string expectedValue)\n        : this(Environment.GetEnvironmentVariable, variable, expectedValue)\n    {\n    }\n\n    public EnvironmentVariableValueRule(Func<string, string?> getEnvironmentVariable, string variable, string expectedValue)\n    {\n        _getEnvironmentVariable = getEnvironmentVariable ?? throw new ArgumentNullException(nameof(getEnvironmentVariable));\n        _variable = variable ?? throw new ArgumentNullException(nameof(variable));\n        _expectedValue = expectedValue ?? throw new ArgumentNullException(nameof(expectedValue));\n    }\n\n    public override bool IsMatch()\n    {\n        var value = _getEnvironmentVariable(_variable);\n        return !string.IsNullOrEmpty(value) && value.Equals(_expectedValue, StringComparison.OrdinalIgnoreCase);\n    }\n}\n\n/// <summary>\n/// Rule that matches when any of the specified environment variables is present and not null/empty,\n/// and returns the associated result value.\n/// </summary>\n/// <typeparam name=\"T\">The type of the result value.</typeparam>\ninternal class EnvironmentDetectionRuleWithResult<T> where T : class\n{\n    private readonly EnvironmentDetectionRule _rule;\n    private readonly T _result;\n\n    public EnvironmentDetectionRuleWithResult(T result, EnvironmentDetectionRule rule)\n    {\n        _rule = rule ?? throw new ArgumentNullException(nameof(rule));\n        _result = result ?? throw new ArgumentNullException(nameof(result));\n    }\n\n    /// <summary>\n    /// Evaluates the rule and returns the result if matched.\n    /// </summary>\n    /// <returns>The result value if the rule matches; otherwise, null.</returns>\n    public T? GetResult()\n    {\n        return _rule.IsMatch()\n            ? _result \n            : null;\n    }\n}    /// See <see cref=\"Commands.Restore.RestoringCommand.RestoreOptimizationProperties\"/> for more details.\n    /// </summary>\n    public static Dictionary<string, string> GetGlobalPropertiesFromArgs(MSBuildArgs msbuildArgs)\n    {\n        var globalProperties = msbuildArgs.GlobalProperties?.ToDictionary() ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);\n        globalProperties[Constants.MSBuildExtensionsPath] = AppContext.BaseDirectory;\n        return globalProperties;\n    }\n\n    /// <summary>\n    /// Applies adjustments to MSBuild arguments to better suit LLM/agentic environments, if such an environment is detected.\n    /// </summary>\n    public static MSBuildArgs AdjustMSBuildForLLMs(MSBuildArgs msbuildArgs, CommandServices services)\n    {\n        if (services.LLMEnvironmentDetector.IsLLMEnvironment())\n        {\n            // disable the live-update display of the TerminalLogger, which wastes tokens\n            return msbuildArgs.CloneWithAdditionalArgs(Constants.TerminalLogger_DisableNodeDisplay);\n        }\n        else\n        {\n            return msbuildArgs;\n        }\n    }\n\n    /// <summary>\n        }\n\n        bool inCI = new CIEnvironmentDetectorForTelemetry().IsCIEnvironment();\n\n        AnsiMode ansiMode = AnsiMode.AnsiIfPossible;\n        // In LLM environments, prefer simple text output so that LLM can parse it easily.\n        // Note that NoAnsi also implies no progress.\n        if (noAnsi || new LLMEnvironmentDetectorForTelemetry(environmentProvider: null).IsLLMEnvironment())\n        {\n            // User explicitly specified --no-ansi.\n            // We should respect that.\n            ansiMode = AnsiMode.NoAnsi;\n        }\n22:    ILLMEnvironmentDetector? llmEnvironmentDetector = null)\n26:    private readonly ILLMEnvironmentDe